/* KORTEX · Hand Thrusters — the hand-reading engine of KORTEX's own hand control (point, pinch, hold, drag). It rides beside the KORTEX
   file, in the same folder, and is loaded only when the Teacher has switched 🖐️ Hand Thrusters on and it is started. Everything here
   runs on this device: no picture or video leaves it, and nothing is saved. Contents: MediaPipe tasks-vision 1.2.2 (Apache License 2.0,
   Google LLC) and its hand landmark model, packed so the page can open them from a USB without any connection. */
(function(){
var P = {"bundle": "", "loader": "", "wasm": "", "model": ""};
function inflate(b64, type){ var bin = atob(b64), u = new Uint8Array(bin.length); for (var i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
  var ds = new DecompressionStream('gzip'); var w = ds.writable.getWriter(); w.write(u); w.close();
  return new Response(ds.readable).arrayBuffer().then(function(ab){ return type ? new Blob([ab], {type: type}) : new Uint8Array(ab); }); }
window.KXHAND_LOAD = function(){
  if (window.KXHAND_READY) return window.KXHAND_READY;
  window.KXHAND_READY = Promise.all([inflate(P.bundle, 'text/javascript'), inflate(P.loader, 'text/javascript'), inflate(P.wasm, 'application/wasm'), inflate(P.model, null)]).then(function(r){
    return new Promise(function(res, rej){ var s = document.createElement('script'); s.src = URL.createObjectURL(r[0]); s.onload = function(){ res(r); }; s.onerror = function(){ rej(new Error('bundle')); }; document.head.appendChild(s); });
  }).then(function(r){
    return Vision.HandLandmarker.createFromOptions({wasmLoaderPath: URL.createObjectURL(r[1]), wasmBinaryPath: URL.createObjectURL(r[2])},
      {baseOptions: {modelAssetBuffer: r[3], delegate: 'CPU'}, runningMode: 'VIDEO', numHands: 1, minHandDetectionConfidence: 0.6, minHandPresenceConfidence: 0.6, minTrackingConfidence: 0.5});
  }).then(function(lm){ window.KXHAND_LM = lm; return lm; });
  return window.KXHAND_READY;
};
})();
